insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('a9e69f4e-b393-4932-b26f-57eb4747e339', 'f5aa7526-c643-437e-ba24-d7b9921c89e7', $$inleiding: streamingdienst Superstream investeert in content en serverparken$$,
   $$economie-vwo-2023-i-content-context1.png$$,
   $$Superstream is een internationaal opererend bedrijf dat abonnementen aanbiedt waarbij klanten tegen een vast jaarbedrag onbeperkt content (films en series) kunnen kijken op telefoon, tablet en tv (streamen). Superstream koopt deze content in bij productiemaatschappijen, deels gefinancierd met nieuw afgesloten kredieten. Het aanbieden van streamingsdiensten vereist forse investeringen in content (eigen films en series) en serverparken (voor het opslaan van data / de content).$$, 'inline'),
  ('0b36f746-ac64-43f9-9b94-b96705eaaaf7', 'f5aa7526-c643-437e-ba24-d7b9921c89e7', $$oligopolie met een niet-kostendekkende prijs; verwachte winst door schaalvoordelen$$,
   $$economie-vwo-2023-i-content-context2.png$$,
   $$Superstream opereert op een oligopolistische markt en voert een niet- kostendekkende prijs. Onder invloed van het stijgende marktaandeel en de aanwezigheid van schaalvoordelen verwacht het bestuur de komende jaren echter wel winst te boeken.$$, 'inline'),
  ('f076b2be-586f-4331-8e73-26604f631360', 'f5aa7526-c643-437e-ba24-d7b9921c89e7', $$drie constateringen van bedrijfsanalist Vierklau$$,
   $$economie-vwo-2023-i-content-context3.png$$,
   $$Bedrijfsanalist Vera Vierklau ziet in haar onderzoek dat er bij de huidige prijs sprake is van een prijsinelastische vraag als door het gevoerde prijsbeleid de concurrentie verdwijnt. Ze constateert het volgende: i. “Door het verdwijnen van de concurrentie verandert de marktvorm. Hierdoor verschuift de prijsafzetfunctie (GO-curve), ii. Door deze verschuiving verandert (bij iedere prijs) de prijselasticiteit van de vraag naar abonnementen. iii. Als Superstream de prijs (matig) verhoogt, zal de omzet stijgen.”$$, 'inline'),
  ('4a16f8f0-7ab7-4d3e-9dc0-c9e05f2f3d18', 'f5aa7526-c643-437e-ba24-d7b9921c89e7', $$figuur 1: opbrengsten en kosten Superstream bij een monopolie$$,
   $$economie-vwo-2023-i-content-context4.png$$,
   $$Figuur 1 opbrengsten en kosten Superstream bij een monopolie
verticale as: P; horizontale as: Q
Lijnen: GO (van P = 200 naar Q = 20), MO (van P = 200 naar Q = 10) en MK = 2 (horizontaal)
GO = 200 – 10Q
MK = 2
GO (=P) = de jaarlijkse abonnementsprijs in euro’s
Q = het aantal abonnementen in miljoenen$$, 'inline'),
  ('adcb988d-4a72-45c4-87af-8511f51a7d37', 'f5aa7526-c643-437e-ba24-d7b9921c89e7', $$Superstream wordt monopolist en streeft naar maximale winst$$,
   $$economie-vwo-2023-i-content-context5.png$$,
   $$Door de toegenomen marktmacht wordt Superstream een monopolist en streeft naar maximale winst.$$, 'inline'),
  ('c64b4b95-4fb9-4e64-9e16-2d89feb2837e', 'f5aa7526-c643-437e-ba24-d7b9921c89e7', $$conclusie Vierklau over omvang en verdeling van het surplus$$,
   $$economie-vwo-2023-i-content-context6.png$$,
   $$Vierklau onderzoekt het totale surplus en kijkt uitsluitend naar figuur 1. Zij concludeert: “De verandering van een niet-kostendekkende prijs naar een monopolieprijs heeft enerzijds effect op de omvang van het surplus in deze markt en anderzijds effect op de verdeling van dat surplus.”$$, 'inline'),
  ('917d034b-8391-4e48-a6dd-dc833e384644', '0c1f1a40-6571-4367-b0a1-b14d27bd094f', $$vereenvoudiging: in Aruba wordt alleen de florin geaccepteerd$$,
   $$economie-vwo-2023-i-aruba-context1.png$$,
   $$In deze opgave wordt er ter vereenvoudiging van uitgegaan dat in Aruba alleen de Arubaanse florin wordt geaccepteerd als betaalmiddel.$$, 'inline'),
  ('fc78c4b7-b79d-4217-bd91-071d5469e212', '0c1f1a40-6571-4367-b0a1-b14d27bd094f', $$vaste wisselkoers van de Arubaanse florin (AWG) ten opzichte van de USD$$,
   $$economie-vwo-2023-i-aruba-context2.png$$,
   $$Aruba heeft een eigen centrale bank en een eigen munt, de Arubaanse florin (AWG). Aruba heeft sinds 1986 een vaste wisselkoersverhouding van de AWG ten opzichte van de (stabiele) Amerikaanse dollar (USD) waarbij 1 AWG = 0,558 USD. De Verenigde Staten zijn een belangrijke handelspartner van Aruba.$$, 'inline'),
  ('9dded346-2e0d-4f75-8507-1fa035010fc1', '0c1f1a40-6571-4367-b0a1-b14d27bd094f', $$vrij kapitaalverkeer en het trilemma van het monetair beleid$$,
   $$economie-vwo-2023-i-aruba-context3.png$$,
   $$Aruba heeft vrij kapitaalverkeer met het buitenland. Er is sprake van een trilemma bij het monetair beleid: de centrale bank van Aruba kan geen onafhankelijke rentepolitiek voeren.$$, 'inline'),
  ('da8eac0a-b894-4819-b611-ae593eadb036', '0c1f1a40-6571-4367-b0a1-b14d27bd094f', $$vraag- en aanbodfuncties van de AWG op de valutamarkt begin 2019$$,
   $$economie-vwo-2023-i-aruba-context4.png$$,
   $$Begin 2019 (= uitgangssituatie) zijn de vraag- en aanbodfuncties van de Arubaanse florin op de valutamarkt op een bepaalde dag als in tabel 1.$$, 'inline'),
  ('2667a593-b5d1-4b7c-a627-bc8dbe4752e9', '0c1f1a40-6571-4367-b0a1-b14d27bd094f', $$tabel 1: vraag- en aanbodfunctie van de AWG$$,
   $$economie-vwo-2023-i-aruba-context5.png$$,
   $$Tabel 1
Qv = –2P + 2,68 Qv = collectieve vraag naar AWG (x miljoen)
P = wisselkoers van de AWG in USD
Qa = 3P – 0,11 Qa = collectieve aanbod van AWG (x miljoen)$$, 'inline'),
  ('f7f0000e-efa8-4264-90ac-efb3f7be70cd', '0c1f1a40-6571-4367-b0a1-b14d27bd094f', $$meer Amerikaanse toeristen; minder Amerikaanse investeringen in Aruba$$,
   $$economie-vwo-2023-i-aruba-context6.png$$,
   $$Medio 2019 kiezen meer Amerikaanse toeristen voor een vakantie naar Aruba als substitutiegoed voor een reis naar Cuba en de Dominicaanse Republiek. Tegelijkertijd investeren Amerikaanse bedrijven niet meer in windturbines en zonnepanelen op Aruba.$$, 'inline'),
  ('73cab04d-14e9-4945-93ce-01e799e1de88', '0c1f1a40-6571-4367-b0a1-b14d27bd094f', $$zonder interventie daalt de wisselkoers naar 0,50 USD$$,
   $$economie-vwo-2023-i-aruba-context7.png$$,
   $$Deze twee ontwikkelingen zorgen voor een tegengesteld effect op de wisselkoers van de AWG in USD. Zonder valuta-interventie daalt de wisselkoers van de AWG naar 0,50 USD.$$, 'inline'),
  ('8dbb766e-b9bf-47d4-ae8d-b3243a5b2107', '0c1f1a40-6571-4367-b0a1-b14d27bd094f', $$recessie in 2020 en de Gini-coëfficiënt van de primaire inkomens$$,
   $$economie-vwo-2023-i-aruba-context8.png$$,
   $$In 2020 veroorzaken recessies in de Verenigde Staten, in het buurland Venezuela en in de Europese Unie een krimpend reëel bruto binnenlands product van Aruba. Met name het toerisme, waar relatief veel huishoudens werkzaam zijn tegen lage inkomens, loopt aanzienlijk terug. Hierdoor kan de Gini-coëfficiënt van de primaire inkomens stijgen.$$, 'inline'),
  ('d8365ab4-874c-49b4-a267-6d9faed0b50f', '0c1f1a40-6571-4367-b0a1-b14d27bd094f', $$voorstel: belastingtarieven op inkomen uit arbeid verlagen$$,
   $$economie-vwo-2023-i-aruba-context9.png$$,
   $$Een econoom wil de recessie bestrijden door de belastingtarieven op inkomen uit arbeid te verlagen.$$, 'inline'),
  ('8d57b576-02b1-4aa1-9f53-9cb28a08d263', '35d66db4-1712-4d16-8889-96a1ee6e8194', $$inleiding: leveranciers verzekeren zich tegen wanbetaling bij een kredietverzekeraar$$,
   $$economie-vwo-2023-i-bij-wanbetaling-afrekenen-context1.png$$,
   $$Tussen bedrijven vinden veel onderlinge leveringen plaats. Doorgaans biedt de leverancier een betalingstermijn aan inkopende bedrijven aan. De leverancier loopt daarbij het risico dat inkopers de betalingstermijn overschrijden en kan daarom een verzekering afsluiten bij een kredietverzekeringsmaatschappij (zie figuur 1). De verzekeraar dekt de schade van de leverancier als er niet of te laat betaald wordt. Tevens levert de verzekeraar een incassodienst als onderdeel van de verzekering.$$, 'inline'),
  ('a0ab6141-e5cd-440b-8270-b43d6420f4d2', '35d66db4-1712-4d16-8889-96a1ee6e8194', $$figuur 1: de kredietverzekering (pijlen 1 t/m 7)$$,
   $$economie-vwo-2023-i-bij-wanbetaling-afrekenen-context2.png$$,
   $$Figuur 1 de kredietverzekering
Schema met drie partijen: leverancier, kredietverzekeraar en inkopende bedrijf, verbonden door de pijlen 1 t/m 7 (zie de afbeelding).
pijl 1: levering verkocht product x
pijl 2: factuurbedrag
pijl 3: premie kredietverzekering
pijl 4: uit te betalen bedrag bij niet betalen door het inkopende bedrijf
pijl 5: eventueel te leveren incassodienst
pijl 6: incassokosten plus opslag
pijl 7: te betalen uitstaande schuld$$, 'inline'),
  ('5fb165a5-16f2-4400-9798-39fbadbf04c2', '35d66db4-1712-4d16-8889-96a1ee6e8194', $$vier verzekeringsvoorwaarden van een kredietverzekeraar$$,
   $$economie-vwo-2023-i-bij-wanbetaling-afrekenen-context3.png$$,
   $$Een econoom onderzoekt de vier verzekeringsvoorwaarden van een kredietverzekeraar:
− Indien het inkopende bedrijf niet betaalt als de betalingstermijn is verstreken, keert de kredietverzekeraar een schadevergoeding uit van 90% van de gemiste omzet aan de leverancier (pijl 4).
− De kredietverzekeraar neemt de incasso van het verschuldigde bedrag op zich als de betalingstermijn is verstreken en het inkopende bedrijf nog steeds niet heeft betaald (pijl 7).
− De kredietverzekeraar rekent de incassokosten door aan het inkopende bedrijf (pijl 6).
− De kredietverzekeraar hanteert een bonus-malussysteem voor de leverancier.$$, 'inline'),
  ('6619ad83-9af9-4fd5-a691-2203a5b9981f', '35d66db4-1712-4d16-8889-96a1ee6e8194', $$stelling: de kredietverzekeraar wordt principaal en het inkopende bedrijf agent$$,
   $$economie-vwo-2023-i-bij-wanbetaling-afrekenen-context4.png$$,
   $$Een econoom stelt: “Als de leverancier een kredietverzekering afsluit en het inkopende bedrijf betaalt niet, neemt de kredietverzekeraar de rol van de principaal over en wordt het inkopende bedrijf de agent. De kredietverzekeraar heeft een voorwaarde opgenomen om dit probleem met de agent te verminderen.”$$, 'inline'),
  ('cbc8bb0c-9d88-486e-bf40-331b4881f7e1', '35d66db4-1712-4d16-8889-96a1ee6e8194', $$angst voor moral hazard door leverancier en inkopend bedrijf$$,
   $$economie-vwo-2023-i-bij-wanbetaling-afrekenen-context5.png$$,
   $$Kredietverzekeraars zijn bang om met moral hazard door zowel de leverancier als het inkopende bedrijf te maken te krijgen.$$, 'inline'),
  ('08f446b8-e702-4966-91fd-7cd574bf7e00', '35d66db4-1712-4d16-8889-96a1ee6e8194', $$Digibate overweegt een kredietverzekering; premie = verwacht schadebedrag + 20% opslag$$,
   $$economie-vwo-2023-i-bij-wanbetaling-afrekenen-context6.png$$,
   $$Digibate levert IT-diensten aan andere bedrijven en hanteert een betalingstermijn. De directie overweegt een kredietverzekering af te sluiten bij de kredietverzekeraar.
De kredietverzekeraar bepaalt de premie op basis van twee factoren:
− het verwachte schadebedrag
− een premieopslag van 20% van het verwachte schadebedrag$$, 'inline'),
  ('ac45dd76-f9ed-4b09-bd70-29273779fdd6', '35d66db4-1712-4d16-8889-96a1ee6e8194', $$kans op wanbetaling op basis van historische data$$,
   $$economie-vwo-2023-i-bij-wanbetaling-afrekenen-context7.png$$,
   $$De kredietverzekeraar bepaalt de kans op wanbetaling op basis van historische data en verzamelt de volgende gegevens van Digibate (zie tabel 1).$$, 'inline'),
  ('0478bcf6-38f4-4909-b6d4-37dc804e8582', '35d66db4-1712-4d16-8889-96a1ee6e8194', $$tabel 1: financiële gegevens Digibate$$,
   $$economie-vwo-2023-i-bij-wanbetaling-afrekenen-context8.png$$,
   $$Tabel 1 financiële gegevens Digibate
aantal contracten | gemiddelde omzet in euro’s | afgesproken betalingstermijn | kans op wanbetaling
20 | 1 miljoen | 90 dagen | 0,05%
30 | 0,5 miljoen | 60 dagen | 0,2%
80 | 0,25 miljoen | 60 dagen | 0,2%$$, 'inline'),
  ('57a6a5d0-2e02-45f4-b0f3-fd9b112e8501', '1d096f81-aeaa-4867-be21-69dc777fa1b0', $$inleiding: visserij in Nambia bij volledige mededinging en risico op overbevissing$$,
   $$economie-vwo-2023-i-achter-het-net-vissen-context1.png$$,
   $$In het land Nambia is de economie voornamelijk gericht op visserij. Ruim de helft van het nationaal inkomen wordt hiermee verdiend. De zeer arbeidsintensieve visserijbedrijven opereren op een markt van volledige mededinging. De overheid van Nambia maakt zich zorgen over het risico op overbevissing en vraagt econoom Laura Haddok onderzoek te doen naar de visstand. De visstand is de totale hoeveelheid beschikbare vis in de wateren voor de kust van Nambia. Econoom Haddok stelt een model op in figuur 1 en tabel 1.$$, 'inline'),
  ('3a226eec-7d37-443a-b7fe-ab1b9872847b', '1d096f81-aeaa-4867-be21-69dc777fa1b0', $$figuur 1: collectieve vismarkt en de marginale kosten per visser$$,
   $$economie-vwo-2023-i-achter-het-net-vissen-context2.png$$,
   $$Figuur 1 collectieve vismarkt en de marginale kosten per visser
linkerdiagram: verticale as P (0 tot 30), horizontale as Q (in tonnen); vraaglijn Qv en aanbodlijn Qa snijden bij P = 18 en Q*
rechterdiagram: verticale as P, MO, MK; horizontale as q (in tonnen); stijgende MK-lijn; bij P = 18 hoort q*$$, 'inline'),
  ('f7bb4516-4303-4658-90ff-f44b288a1a6d', '1d096f81-aeaa-4867-be21-69dc777fa1b0', $$tabel 1: model van de collectieve vismarkt in Nambia$$,
   $$economie-vwo-2023-i-achter-het-net-vissen-context3.png$$,
   $$Tabel 1 model van de collectieve vismarkt in Nambia
Qv = binnenlandse vraag naar vis per maand in tonnen | Qv = 6.000 – 125P
P = prijs van een ton vis in lokale munt (badi)
Qa = binnenlands aanbod van vis per maand in tonnen | Qa = 375P – 3.000
omvang visstand | 80.000 ton
maandelijkse groei visstand | 3%$$, 'inline'),
  ('2fba8306-e3e0-4b86-bec4-abdf52e4a828', '1d096f81-aeaa-4867-be21-69dc777fa1b0', $$vaste kosten worden achterwege gelaten$$,
   $$economie-vwo-2023-i-achter-het-net-vissen-context4.png$$,
   $$In dit model worden de vaste (constante) kosten achterwege gelaten.$$, 'inline'),
  ('4375d31a-80ed-4107-b10a-2c800c395c1f', '1d096f81-aeaa-4867-be21-69dc777fa1b0', $$stelling Haddok: de visindustrie verslechtert steeds sneller$$,
   $$economie-vwo-2023-i-achter-het-net-vissen-context5.png$$,
   $$Econoom Haddok stelt dat bij een evenwicht op de collectieve vismarkt in Nambia, en als de huidige situatie zich voortzet, de toekomst van de visindustrie in Nambia steeds sneller zal verslechteren.$$, 'inline'),
  ('4fc1c0d5-1dd8-48d3-b84c-1edf7455d347', '1d096f81-aeaa-4867-be21-69dc777fa1b0', $$investeringen in innovatieve technologie; reactie van Haddok (i t/m iii)$$,
   $$economie-vwo-2023-i-achter-het-net-vissen-context6.png$$,
   $$Visserijbedrijven willen investeren in innovatieve technologieën om hun visvangst en hun marktpositie te verbeteren. Haddok onderzoekt dit en reageert met behulp van figuur 1: i “Door de investeringen veranderen de kosten voor een individuele visser en verschuift een curve in het rechterdiagram, ii Daardoor verandert het evenwicht op de collectieve markt, iii Hierdoor zal de situatie van overbevissing juist verder verslechteren.”$$, 'inline'),
  ('9e689cd6-e792-4b33-a426-b4e1593457cc', '1d096f81-aeaa-4867-be21-69dc777fa1b0', $$heffing per ton vis om overbevissing te stoppen$$,
   $$economie-vwo-2023-i-achter-het-net-vissen-context7.png$$,
   $$Om overbevissing te stoppen moet de visvangst gelijk zijn aan de groei. Om dit te bereiken zou de overheid een heffing per ton vis kunnen opleggen.$$, 'inline'),
  ('0c74d629-e738-4616-9e10-54e99e568de8', '1d096f81-aeaa-4867-be21-69dc777fa1b0', $$vergunningen met een visquotum onder twee voorwaarden$$,
   $$economie-vwo-2023-i-achter-het-net-vissen-context8.png$$,
   $$De overheid wil vergunningen uitgeven met een visquotum. Haddok zegt hierover: “Het uitgeven van vergunningen kan de overbevissing ook stoppen. Maar er moet worden voldaan aan twee voorwaarden.”$$, 'inline'),
  ('f176327f-3b83-4cc4-9092-db5f5b9f9cfb', 'b8f28aa6-8403-4db1-be53-fb57fd1773b4', $$inleiding: verlaging algemene heffingskorting levert € 2 miljard op; gesloten economie$$,
   $$economie-vwo-2023-i-belastingverhoging-context1.png$$,
   $$De regering van een land discussieert over mogelijkheden om het bestaande overheidstekort terug te dringen. Een van de opties is het verlagen van de algemene heffingskorting bij de inkomstenbelasting, dat levert € 2 miljard extra autonome belastinginkomsten op. Econoom Maria Kempes onderzoekt deze optie, waarbij ze uitgaat van een gesloten economie.$$, 'inline'),
  ('1e67956e-e12a-4651-bee1-01ed5c75734d', 'b8f28aa6-8403-4db1-be53-fb57fd1773b4', $$bewering Kempes over multiplierwerking$$,
   $$economie-vwo-2023-i-belastingverhoging-context2.png$$,
   $$Kempes beweert: “Op basis van tabel 1 blijkt dat de nominale daling van het bbp groter is dan de nominale daling van de algemene heffingskorting. Dat is het gevolg van de multiplierwerking.”$$, 'inline'),
  ('c9b67fbb-c46f-432c-84a2-8caa160e5a62', 'b8f28aa6-8403-4db1-be53-fb57fd1773b4', $$verwachting Kempes: nieuw evenwicht bij 5,6% rente en 1,3% inflatie (IS-MB-GA-model)$$,
   $$economie-vwo-2023-i-belastingverhoging-context3.png$$,
   $$Kempes: “Ik verwacht dat de verlaging van de algemene heffingskorting leidt tot een afname van het bbp en dat na verloop van tijd de economie een nieuw evenwicht bereikt bij een rente van 5,6% en een stabiele inflatie van 1,3%. Dit analyseer ik met behulp van het IS-MB-GA-model zoals getoond in figuur 1.”$$, 'inline'),
  ('b017a781-038b-46eb-9f18-1b0991bc6832', 'b8f28aa6-8403-4db1-be53-fb57fd1773b4', $$conclusie Kempes als de centrale bank de rente op 8% had gehouden$$,
   $$economie-vwo-2023-i-belastingverhoging-context4.png$$,
   $$De gewenste verbetering van het overheidssaldo is mede afhankelijk van het rentebeleid van de centrale bank. Kempes concludeert: “Als de centrale bank de rente op 8% had gehouden, zou de overheid extra moeten bezuinigen om uiteindelijk de beoogde verbetering van het overheidssaldo te realiseren.”$$, 'inline'),
  ('fe7262b9-bc04-4f0c-b6b1-1e2b016fb5ea', 'b8f28aa6-8403-4db1-be53-fb57fd1773b4', $$kritiek van Tango vanuit een monetaristische visie$$,
   $$economie-vwo-2023-i-belastingverhoging-context5.png$$,
   $$Econoom Gabriel Tango uit kritiek op de Keynesiaanse visie in het model van Kempes. Tango stelt: “Als je een monetaristische visie had gehad, zou de centrale bank de rente niet zo ver hoeven te verlagen om haar doelstelling te behalen.”$$, 'inline'),
  ('2e6c4838-465a-4b47-ac4b-9fb39dbd60e7', 'b8f28aa6-8403-4db1-be53-fb57fd1773b4', $$tabel 1: enkele uitkomsten van het model$$,
   $$economie-vwo-2023-i-belastingverhoging-context6.png$$,
   $$Tabel 1 enkele uitkomsten van het model
rente | aanpassing algemene heffingskorting (in miljarden) | overheidsbestedingen (in miljarden) | consumptie (in miljarden) | bbp (in miljarden)
8% | | 100 | 180 | 330
8% | –2 | 100 | 177 | 327
5,6% | –2 | 100 | 178,5 | 330$$, 'inline'),
  ('59a7999d-5239-4fc6-8099-2747918cd7da', 'b8f28aa6-8403-4db1-be53-fb57fd1773b4', $$figuur 1: grafische weergave van het IS-MB-GA-model$$,
   $$economie-vwo-2023-i-belastingverhoging-context7.png$$,
   $$Figuur 1 grafische weergave van het IS-MB-GA-model
bovenste diagram: verticale as rente (r), horizontale as inkomen (Y); dalende lijnen IS₀ en IS₁ (gestippeld, links van IS₀); horizontale lijnen MB₀ bij 8,0 en MB₁ bij 5,6; verticale hulplijnen bij Y = 327 en Y = 330
onderste diagram: verticale as inflatie π (%), horizontale as inkomen (Y); stijgende lijnen GA₀ en GA₁ (gestippeld, rechts van GA₀); hulplijnen bij π = 2,0 en π = 1,3 en bij Y = 327 en Y = 330$$, 'inline'),
  ('cf2efd81-b62d-436d-bd05-5fffca135c38', 'e558d3bf-2db8-4043-b120-fc9100fc9582', $$inleiding: circulaire economie en recycling$$,
   $$economie-vwo-2023-i-circulaire-economie-context1.png$$,
   $$Milieueconomen pleiten voor een circulaire economie. Bij een circulaire economie wordt afval zoveel mogelijk vermeden en het afval dat nog ontstaat, wordt hergebruikt. Een onderzoeksbureau analyseert de mogelijkheden om de economie meer circulair te maken (zie figuur 1). Het onderzoeksbureau neemt aan dat recycling minder milieuvervuilend is dan productie met niet-hernieuwbare grondstoffen.$$, 'inline'),
  ('a250f7aa-3585-4c2e-951a-08d1061f9b2b', 'e558d3bf-2db8-4043-b120-fc9100fc9582', $$figuur 1: de lineaire en circulaire economie$$,
   $$economie-vwo-2023-i-circulaire-economie-context2.png$$,
   $$Figuur 1 de lineaire en circulaire economie
voorraad niet-hernieuwbare grondstoffen → productie → consumptie → niet gerecycled afval
Circulaire stromen (gestippeld): A van consumptie naar recycling, B van productie naar recycling, C van recycling naar productie.
Legenda:
→ goederenstroom bij een lineaire economie
⇢ goederenstroom die de economie circulair maken$$, 'inline'),
  ('c28cd33e-1b1e-49b8-99a7-1be68cd633b6', 'e558d3bf-2db8-4043-b120-fc9100fc9582', $$stelling: een circulaire economie kan het groen bbp verhogen$$,
   $$economie-vwo-2023-i-circulaire-economie-context3.png$$,
   $$Milieueconomen stellen: een circulaire economie kan in de toekomst het groen bbp verhogen.$$, 'inline'),
  ('9ae3b996-7a90-4dbe-87f0-325c0081186f', 'e558d3bf-2db8-4043-b120-fc9100fc9582', $$opmerking: bij uitputting van grondstoffen neemt stroom A toe$$,
   $$economie-vwo-2023-i-circulaire-economie-context4.png$$,
   $$Het onderzoeksbureau merkt op: “Bij uitputting van niet-hernieuwbare grondstoffen zal marktwerking leiden tot andere prijzen, waardoor stroom
A zal toenemen.”$$, 'inline'),
  ('7f774b36-47a4-4552-b9df-46d05cf6250c', 'e558d3bf-2db8-4043-b120-fc9100fc9582', $$statiegeld op plastic flesjes als prijsprikkel$$,
   $$economie-vwo-2023-i-circulaire-economie-context5.png$$,
   $$Het onderzoeksbureau stelt dat de overheid een circulaire economie kan bevorderen door prijsprikkels. Een voorbeeld is statiegeld op plastic flesjes. De consument krijgt het statiegeld uitsluitend terug bij inlevering van het flesje.$$, 'inline'),
  ('4ca7f591-e596-49f3-8585-ca5eee556206', 'e558d3bf-2db8-4043-b120-fc9100fc9582', $$casus: Cirkel levert afval aan Schoon, die een specifieke installatie moet aanschaffen$$,
   $$economie-vwo-2023-i-circulaire-economie-context6.png$$,
   $$Het onderzoeksbureau bekijkt een casus van twee bedrijven. Bedrijf ‘Cirkel’ heeft een productieproces waarbij afval vrijkomt, maar heeft tot nu toe niet zelf geïnvesteerd in het scheiden van het afval. Nu levert het bedrijf het afval aan bedrijf ‘Schoon’, die het afval kan scheiden. Daarvoor moet bedrijf Schoon wel investeren in een nieuwe verwerkingsinstallatie, die specifiek wordt gemaakt om het afval van Cirkel te verwerken.$$, 'inline'),
  ('2360d8a6-5fff-4fa3-a720-6bd4d617e6bc', 'e558d3bf-2db8-4043-b120-fc9100fc9582', $$relevante gegevens van bedrijf Schoon$$,
   $$economie-vwo-2023-i-circulaire-economie-context7.png$$,
   $$Relevante gegevens van bedrijf Schoon:
− Opbrengst: € 6 per kilogram verwerkt afval.
− Variabele kosten: € 2 per kilogram verwerkt afval + de inkoopkosten van afval per kilogram (van Cirkel).
− Vaste (constante) kosten: € 180.000 per jaar, waarvan driekwart als verzonken kosten kunnen worden aangemerkt.
− Er wordt 100.000 kilogram afval per jaar verwerkt.$$, 'inline'),
  ('2bceed91-3956-4061-a4d3-b921aaee9df1', 'e558d3bf-2db8-4043-b120-fc9100fc9582', $$Schoon schaft de installatie aan; Cirkel eist daarna een hogere prijs$$,
   $$economie-vwo-2023-i-circulaire-economie-context8.png$$,
   $$Schoon wil anticiperen op mogelijke concurrenten en besluit na een mondeling overleg met Cirkel de verwerkingsinstallatie aan te schaffen. Bij de definitieve contractonderhandelingen eist Cirkel een hogere prijs dan Schoon bereid is te betalen.$$, 'inline');

