   '[{"domain": "Goede tijden, slechte tijden", "subdomain": "Conjunctuuranalyse aan de hand van IS-MB-GA-model"}, {"domain": "Goede tijden, slechte tijden", "subdomain": "Begrotingsbeleid"}]'::jsonb,
   '["multiplier berekenen", "Keynesiaanse kruis", "heffingskorting", "autonome belastingen", "bestedingseffect"]'::jsonb,
